// Post-processes the sitemap generated by @astrojs/sitemap:
//  - keeps only indexable pages (drafts and noindex pages are removed) and adds <lastmod> from each page's `updated` meta;
//  - splits the result into child sitemaps (pages, menu, guides, ta) listed in sitemap-index.xml;
//  - adds <image:image> entries for descriptive, alt-texted content photos on each page.
// hreflang alternates written by @astrojs/sitemap (i18n) are preserved.
import fs from 'node:fs';
import path from 'node:path';
import { args, htmlFiles, loadPage } from './_lib.mjs';

const { dist } = args();
const pages = new Map(htmlFiles(dist).map((f) => { const p = loadPage(dist, f); return [p.path, p]; }));
const smPath = path.join(dist, 'sitemap-0.xml');
const idxPath = path.join(dist, 'sitemap-index.xml');

if (!fs.existsSync(smPath)) {
  console.log('postbuild-sitemap: no sitemap-0.xml generated (no pages?)');
  process.exit(0);
}
const xml = fs.readFileSync(smPath, 'utf8');
const head = xml.slice(0, xml.indexOf('<url>') === -1 ? xml.indexOf('</urlset>') : xml.indexOf('<url>'));
const blocks = xml.match(/<url>[\s\S]*?<\/url>/g) ?? [];
const idxXml = fs.existsSync(idxPath) ? fs.readFileSync(idxPath, 'utf8') : '';
const origin = new URL(xml.match(/<loc>(.*?)<\/loc>/)?.[1] ?? idxXml.match(/<loc>(.*?)<\/loc>/)?.[1] ?? 'https://example.com/').origin;

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const SKIP_IMG = /logo-mark|favicon|icon-|apple-touch|\/og\//;
function imageEntries(page) {
  const seen = new Set();
  const out = [];
  for (const img of page.root.querySelectorAll('img')) {
    const src = img.getAttribute('src');
    const alt = (img.getAttribute('alt') ?? '').trim();
    if (!src || !alt || SKIP_IMG.test(src) || seen.has(src)) continue;
    seen.add(src);
    const abs = src.startsWith('http') ? src : origin + (src.startsWith('/') ? '' : '/') + src;
    out.push(`<image:image><image:loc>${esc(abs)}</image:loc></image:image>`);
    if (out.length >= 20) break;
  }
  return out.join('');
}

const groupOf = (p) => (p.startsWith('/menu/') ? 'menu' : p.startsWith('/guides/') ? 'guides' : p.startsWith('/ta/') ? 'ta' : 'pages');
const groups = { pages: [], menu: [], guides: [], ta: [] };
let kept = 0, dropped = 0, images = 0;
for (const b of blocks) {
  const loc = b.match(/<loc>(.*?)<\/loc>/)[1];
  const p = new URL(loc).pathname;
  const page = pages.get(p);
  if (!page || page.noindex) { dropped++; continue; }
  const lastmod = page.updated ? `<lastmod>${page.updated}</lastmod>` : '';
  const imgs = imageEntries(page);
  if (imgs) images += (imgs.match(/<image:image>/g) ?? []).length;
  groups[groupOf(p)].push(b.replace(/<\/loc>/, `</loc>${lastmod}`).replace(/<\/url>$/, `${imgs}</url>`));
  kept++;
}

const children = [];
for (const [name, list] of Object.entries(groups)) {
  if (list.length === 0) continue;
  const file = `sitemap-${name}.xml`;
  fs.writeFileSync(path.join(dist, file), `${head}${list.join('')}</urlset>`);
  children.push(file);
}
fs.rmSync(smPath, { force: true });
const today = new Date().toISOString().slice(0, 10);
fs.writeFileSync(
  idxPath,
  `<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${children.map((f) => `<sitemap><loc>${origin}/${f}</loc><lastmod>${today}</lastmod></sitemap>`).join('')}</sitemapindex>`,
);
console.log(`postbuild-sitemap: ${kept} URLs kept in ${children.length} child sitemap(s) (${children.join(', ') || 'none'}), ${images} image entries, ${dropped} draft/noindex URLs removed`);
if (kept === 0) console.log('  (sitemap is empty: every page is still a draft)');
